Actionscript.script:
// 大学敌人时间轴：敌人 AI 决定入口，帧事件只负责本次攻击。
连招下一段 = undefined;
待发兵器子弹 = undefined;
function 攻击有效()
{
    return _parent.man === this && _parent.hp > 0 && (_parent.状态 == "空手攻击" || _parent.状态 == "近战");
}
function 发射兵器子弹(子弹参数)
{
    if (!攻击有效()) return;
    // 换刀姿势可能先执行帧脚本，再执行刀口的 load；只保留本帧请求。
    if (!刀.刀.装扮.刀口位置1)
    {
        if (!待发兵器子弹) 待发兵器子弹 = [];
        待发兵器子弹.push({帧:_currentframe, 参数:子弹参数});
        return;
    }
    _parent.刀口位置生成子弹(_parent, 子弹参数);
}
function 提交待发攻击()
{
    if (!待发兵器子弹) return;
    var 待发 = 待发兵器子弹;
    待发兵器子弹 = undefined;
    if (!攻击有效()) return;
    if (!刀.刀.装扮.刀口位置1)
    {
        待发兵器子弹 = 待发;
        return;
    }
    for (var i = 0; i < 待发.length; i++)
    {
        if (待发[i].帧 == _currentframe)
        {
            _parent.刀口位置生成子弹(_parent, 待发[i].参数);
        }
    }
}
function 攻击时移动(速度)
{
    if (!攻击有效()) return;
    // 此函数属于当前攻击动画，直接使用它的父级，避免跨时间轴的 _parent 解析。
    var 移动方向 = _parent.方向;
    if (速度 < 0)
    {
        速度 = -速度;
        移动方向 = 移动方向 == "右" ? "左" : "右";
    }
    _parent.移动(移动方向, 速度);
}
function 攻击时可改变移动方向(速度)
{
    攻击时移动(速度);
}
function 攻击时斜向移动(慢速度, 快速度)
{
    攻击时移动(慢速度);
}
function 攻击时可斜向改变移动方向(速度)
{
    攻击时移动(速度);
    if (!攻击有效()) return;
    var 目标 = _root.gameworld[_parent.攻击目标];
    if (!(目标.hp > 0)) return;
    var 距离 = 目标.Z轴坐标 - _parent.Z轴坐标;
    if (isNaN(距离)) return;
    var 移动方向 = 距离 < 0 ? "上" : "下";
    距离 = Math.abs(距离);
    if (速度 > 0 && 距离 > 速度 / 2) 距离 = 速度 / 2;
    _parent.移动(移动方向, 距离);
}
function 变招判定(招式名, 招式是否结束)
{
    if (攻击有效() && !招式是否结束)
    {
        连招下一段 = 招式名;
    }
}
function 完成本段()
{
    stop();
    if (!攻击有效())
    {
        if (_parent.hp <= 0) _parent.动画完毕();
        return;
    }
    var 目标 = _root.gameworld[_parent.攻击目标];
    if (连招下一段 && 目标.hp > 0)
    {
        gotoAndPlay(连招下一段);
    }
    else
    {
        _parent.动画完毕();
    }
}
function 刀口触发特效(状态名)
{
    if (攻击有效() && _parent.特效刀口)
    {
        _parent.特效刀口.特效刀口触发(状态名);
    }
}
function 兵器攻击(子弹威力, Z轴攻击范围, 击倒率, 水平击退速度, 垂直击退速度)
{
	var 子弹参数 = new Object();
	子弹参数.子弹威力 = 子弹威力;
	if (_parent.被动技能.刀剑攻击 && _parent.被动技能.刀剑攻击.启用)
	{
		子弹参数.子弹威力 +=  _parent.刀属性.power * _parent.被动技能.刀剑攻击.等级 * 0.075;
	}
	if (_parent.mp攻击加成)
	{
		子弹参数.子弹威力 += _parent.mp攻击加成;
	}
	子弹参数.Z轴攻击范围 = Z轴攻击范围;
	子弹参数.击中后子弹的效果 = "斩打命中特效";
	子弹参数.击倒率 = 击倒率;
	子弹参数.水平击退速度 = 水平击退速度;
	if(垂直击退速度){
		子弹参数.垂直击退速度 = 垂直击退速度;
	}

	if (攻击有效())
	{
		发射兵器子弹(子弹参数);
	}
}

// 本素材保留六套旧动作。新物品分类没有同名帧时沿用通用刀剑动作。
var 动作前缀 = _parent.兵器动作类型;
if (动作前缀 != "狂野" && 动作前缀 != "长柄" && 动作前缀 != "刀剑" && 动作前缀 != "长枪" && 动作前缀 != "长棍")
{
    动作前缀 = "";
}
if (动作前缀 != "") gotoAndPlay(动作前缀 + "1连招");

子弹威力 = _parent.空手攻击力 / 5 + _parent.刀属性.power;
Z轴攻击范围 = 30;
击倒率 = 10;
